-- Original installed native learning domains; keep knowledge separate from placement/crafting.

CREATE TABLE native_furniture_learning_actions (
 item_ref integer PRIMARY KEY CHECK(item_ref>0), action_id integer NOT NULL CHECK(action_id>0),
 learned_refs integer[] NOT NULL CHECK(cardinality(learned_refs)>0),
 template_ids bigint[] NOT NULL CHECK(cardinality(template_ids)=cardinality(learned_refs)),
 has_criteria boolean NOT NULL, source_sha256 text NOT NULL
);

CREATE TABLE native_recipe_learning_actions (
 item_ref integer PRIMARY KEY CHECK(item_ref>0), action_id integer NOT NULL CHECK(action_id>0),
 native_class text NOT NULL CHECK(native_class IN ('bIB','bIz')), profession_id integer NOT NULL CHECK(profession_id>0),
 recipe_ids integer[] NOT NULL CHECK(cardinality(recipe_ids)>0), has_criteria boolean NOT NULL,
 source_sha256 text NOT NULL
);
CREATE TABLE recipe_learning_receipts (
 account_id bigint NOT NULL REFERENCES accounts(id), source_uid bigint NOT NULL CHECK(source_uid>0),
 character_id bigint NOT NULL REFERENCES characters(id), source_ref integer NOT NULL CHECK(source_ref>0),
 action_id integer NOT NULL CHECK(action_id>0), profession_id integer NOT NULL CHECK(profession_id>0),
 recipe_ids integer[] NOT NULL CHECK(cardinality(recipe_ids)>0), created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(account_id,source_uid)
);

CREATE TABLE native_bag_view_learning_actions (
 item_ref integer PRIMARY KEY CHECK(item_ref>0), action_id integer NOT NULL CHECK(action_id>0),
 view_id integer NOT NULL CHECK(view_id>0), has_criteria boolean NOT NULL, source_sha256 text NOT NULL
);
CREATE TABLE bag_view_learning_receipts (
 account_id bigint NOT NULL REFERENCES accounts(id), source_uid bigint NOT NULL CHECK(source_uid>0),
 character_id bigint NOT NULL REFERENCES characters(id), source_ref integer NOT NULL CHECK(source_ref>0),
 action_id integer NOT NULL CHECK(action_id>0), view_id integer NOT NULL CHECK(view_id>0),
 created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(account_id,source_uid)
);

CREATE TABLE native_mimisymbic_learning_actions (
 item_ref integer PRIMARY KEY CHECK(item_ref>0), action_id integer NOT NULL CHECK(action_id>0),
 native_class text NOT NULL CHECK(native_class='bHv'), has_criteria boolean NOT NULL, source_sha256 text NOT NULL
);
CREATE TABLE mimisymbic_learning_receipts (
 account_id bigint NOT NULL REFERENCES accounts(id), source_uid bigint NOT NULL CHECK(source_uid>0),
 character_id bigint NOT NULL REFERENCES characters(id), source_ref integer NOT NULL CHECK(source_ref>0),
 action_id integer NOT NULL CHECK(action_id>0), target_uid bigint NOT NULL CHECK(target_uid>0),
 target_ref integer NOT NULL CHECK(target_ref>0), categories integer[] NOT NULL CHECK(cardinality(categories)>0),
 appearance_ref integer NOT NULL CHECK(appearance_ref>0), created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(account_id,source_uid)
);

CREATE TABLE native_mimisymbic_targets (
 target_ref integer NOT NULL CHECK(target_ref>0), appearance_ref integer NOT NULL CHECK(appearance_ref>0),
 category integer NOT NULL CHECK(category BETWEEN 8 AND 14), source_sha256 text NOT NULL,
 PRIMARY KEY(target_ref,category)
);
